"""Integer constant expressions, using C precedence and short-circuiting."""
import re
import ast

PRECEDENCE = {',':1,'=':2,'+=':2,'-=':2,'*=':2,'/=':2,'%=':2,'<<=':2,'>>=':2,'&=':2,'^=':2,'|=':2,
              '?':3,'||':4,'&&':5,'|':6,'^':7,'&':8,'==':9,'!=':9,'<':10,'>':10,'<=':10,'>=':10,
              '<<':11,'>>':11,'+':12,'-':12,'*':13,'/':13,'%':13}


def number(s):
    s=s.strip()
    if "'" in s:
        st=s[s.index("'"):]
        try: chars=ast.literal_eval(st)
        except Exception:
            chars=st[1:-1]
        n=0
        for c in chars:n=(n<<8)+ord(c)
        return n
    s=re.sub(r'[uUlLfF]+$','',s)
    if not s:return 0
    if re.match('^0[xX]',s):
        if '.' in s or 'p' in s.lower():return float.fromhex(s)
        return int(s,16)
    if s.startswith(('0b','0B')):return int(s,2)
    if '.' in s or 'e' in s.lower():return float(s)
    if len(s)>1 and s.startswith('0'):return int(s,8)
    return int(s,10)


def apply(op,a,b):
    if op=='+':return a+b
    if op=='-':return a-b
    if op=='*':return a*b
    if op=='/':return int(a/b) if isinstance(a,float) or isinstance(b,float) else (abs(a)//abs(b))*(-1 if (a<0) != (b<0) else 1)
    if op=='%':return a-apply('/',a,b)*b
    if op=='<<':return int(a)<<(int(b)&63)
    if op=='>>':return int(a)>>(int(b)&63)
    if op=='|':return int(a)|int(b)
    if op=='&':return int(a)&int(b)
    if op=='^':return int(a)^int(b)
    if op=='==':return int(a==b)
    if op=='!=':return int(a!=b)
    if op=='<':return int(a<b)
    if op=='>':return int(a>b)
    if op=='<=':return int(a<=b)
    if op=='>=':return int(a>=b)
    if op=='&&':return int(bool(a) and bool(b))
    if op=='||':return int(bool(a) or bool(b))
    if op==',':return b
    raise ValueError(op)

class ConstExpr:
    def __init__(self, tokens):
        self.tokens=tokens;self.i=0
    def peek(self):
        return self.tokens[self.i] if self.i<len(self.tokens) else '<eof>'
    def take(self):
        t=self.peek();self.i+=1;return t
    def expression(self, minimum=1, evaluate=True):
        t=self.take()
        if t in ('+','-','!','~'):
            v=self.expression(14,evaluate)
            if evaluate:
                v={'+':lambda:+v,'-':lambda:-v,'!':lambda:int(not v),'~':lambda:~int(v)}[t]()
        elif t=='(':
            v=self.expression(1,evaluate)
            if self.take()!=')':raise ValueError(')')
        else:
            v=number(t) if evaluate else 0
        while PRECEDENCE.get(self.peek(),0)>=minimum:
            op=self.take();p=PRECEDENCE[op]
            if p==2:raise ValueError(op)
            if op=='?':
                y=self.expression(1,evaluate and bool(v))
                if self.take()!=':':raise ValueError(':')
                n=self.expression(3,evaluate and not bool(v))
                v=y if v else n
                continue
            ev=evaluate and not ((op=='&&' and not v) or (op=='||' and v))
            b=self.expression(p+1,ev)
            v=apply(op,v,b) if evaluate else 0
        return v
    def run(self):
        result=self.expression()
        if self.i!=len(self.tokens):raise ValueError('extra')
        return result
