"""A token-based C preprocessor with include tracking and line control."""
import os
import re
import datetime
from dataclasses import dataclass
from .common import Token, StopCompilation
from .lexer import lex, significant, normalized, spell, IDENT_RE
from .constexpr import ConstExpr

SYSTEM_INCLUDES = ['/usr/local/include/x86_64-linux-gnu','/usr/local/include',
                   '/usr/include/x86_64-linux-gnu','/usr/include']
SYSTEM_LIBRARIES = ['/usr/lib/x86_64-linux-gnu','/usr/lib','/lib/x86_64-linux-gnu',
                    '/lib','/usr/local/lib/x86_64-linux-gnu','/usr/local/lib']

@dataclass
class Macro:
    name: str
    params: object
    body: list
    variadic: object = None
    def declaration(self):
        text='#define '+self.name
        if self.params is not None:
            args=list(self.params)
            if self.variadic is not None:
                if self.variadic=='__VA_ARGS__':args[-1]='...'
                else:args[-1]+='...'
            text+='('+','.join(args)+')'
        val=spell(self.body)
        if val:text+=' '+val
        return text

class Renderer:
    def __init__(self,options):
        self.options=options;self.output=[];self.file=None;self.nextline=1
        self.enabled=options.action=='preprocess'
    @property
    def lines(self):
        return self.options.pp_mode != 0 and self.options.dump_macros != 2
    def marker(self,line,file,flag=0):
        self.file=file;self.nextline=line
        if not self.enabled or not self.lines:return
        escaped=file.replace('\\','\\\\').replace('"','\\"')
        if self.options.pp_mode==1:
            text='#line %d "%s"\n'%(line,escaped)
        else:
            text='# %d "%s"%s\n'%(line,escaped,' '+str(flag) if flag else '')
        self.output.append(text)
    def sync(self,line,file):
        if not self.enabled:return
        if self.lines:
            delta=line-self.nextline
            if file!=self.file or delta<0 or delta>=8:
                self.marker(line,file)
            elif delta:
                self.output.append('\n'*delta)
                self.nextline=line
        else:
            self.file=file;self.nextline=line
    def emit(self,text,line,file,directive=False):
        if not self.enabled:return
        if self.options.dump_macros==2 and not directive:return
        if not text.strip():return
        self.sync(line,file)
        self.output.append(text.rstrip()+'\n')
        self.file=file;self.nextline=line+1
    def diagnostic_break(self):
