                    '/lib','/usr/local/lib/x86_64-linux-gnu','/usr/local/lib']

@dataclass
class Macro:
    name: str
    params: object
    body: list
    variadic: object = None
    def declaration(self):
        text='#define '+self.name
        if self.params is not None:
            args=list(self.params)
            if self.variadic is not None:
                if self.variadic=='__VA_ARGS__':args[-1]='...'
                else:args[-1]+='...'
            text+='('+','.join(args)+')'
        val=spell(self.body)
        if val:text+=' '+val
        return text

