            delta=line-self.nextline
            if file!=self.file or delta<0 or delta>=8:
                self.marker(line,file)
            elif delta:
                self.output.append('\n'*delta)
                self.nextline=line
        else:
            self.file=file;self.nextline=line
    def emit(self,text,line,file,directive=False):
        if not self.enabled:return
        if self.options.dump_macros==2 and not directive:return
        if not text.strip():return
        self.sync(line,file)
        self.output.append(text.rstrip()+'\n')
