#!/usr/bin/env python3
"""Command-line entry point for the independent compiler implementation."""
import os
import sys
from pathlib import Path
from cfront.common import Options, Diagnostic, StopCompilation
from cfront.options import parse_arguments, Immediate, VERSION, search_dirs
from cfront.preprocessor import Preprocessor, SYSTEM_LIBRARIES


def default_output(file,object=False):
    if file=='-':return 'a.out'
    return os.path.splitext(os.path.basename(file))[0]+('.o' if object else '')


def main(argv=None):
    args=list(sys.argv[1:] if argv is None else argv)
    o=Options();d=Diagnostic(o);out=[];code=0;pps=[];showversion=True
    output_file=None
    try:
        parse_arguments(args,o,d)
        if o.verbose:out.append(VERSION)
        showversion=False
        if o.action=='preprocess' and o.output:
            try:output_file=open(o.output,'w',encoding='utf-8',errors='surrogateescape')
            except OSError:d.error("could not write '%s'"%o.output)
        sources=[];programs=[]
        for kind,name,lang in o.inputs:
            if kind=='library':
                candidates=[]
                for p in o.libraries+([o.root]+SYSTEM_LIBRARIES if not o.no_libpath else []):
                    for ext in ('.a',) if o.static else ('.so','.a'):
                        candidates.append(p+'/lib'+name+ext)
                if not any(os.path.exists(x) for x in candidates):d.error("library '%s' not found"%name)
                continue
            if o.verbose:
                shown='<stdin>' if name=='-' and o.verbose>=2 else name
                out.append('-> '+shown+'\n')
            try:
                if name=='-':source=sys.stdin.read()
                else:
                    with open(name,encoding='utf-8',errors='surrogateescape') as f:source=f.read()
            except OSError:d.error("file '%s' not found"%name)
            if lang=='binary' or (lang is None and name!='-' and not name.endswith(('.c','.h','.i','.S','.s','.C','.cpp'))):
                if source.startswith('\x7fELF') or source.startswith('!<arch>\n'):continue
                d.error("unrecognized file type",None)
            pp=Preprocessor(o,d,out);pps.append(pp)
            tokens=pp.start(name,source)
            sources.append(name)
            if o.action not in ('preprocess','depend'):
                from cfront.parser import Parser
                program=Parser(tokens,o,d).parse()
                programs.append(program)
                if o.action=='object':
                    from cfront.elf import write_object
                    dest=o.output or default_output(name,True)
                    write_object(dest,[program],o,d)
                    if o.verbose:out.append('<- '+dest+'\n')
            d.pp=None
        if o.action in ('depend',) or (o.deps and o.action in ('preprocess','object','reloc')):
            target=o.output or default_output(sources[0] if sources else '-',True)
            deps=[]
            for pp in pps:
                for f in pp.dependencies:
                    if o.deps==2 and f in pp.sysdeps:continue
                    if f not in deps:deps.append(f)
            text=target+':'+''.join(' \\\n  '+f for f in deps)+'\n'
            dest=o.depfile
            if o.action!='depend' and not dest:dest=os.path.splitext(target)[0]+'.d'
            if dest:
                try:Path(dest).write_text(text)
                except OSError:d.error("could not write '%s'"%dest)
            else:out.append(text)
        elif o.action=='reloc':
            from cfront.elf import write_object
            dest=o.output or 'a.out';write_object(dest,programs,o,d)
        elif o.action in ('link','run','shared'):
            from cfront.linker import link
            code=link(programs,o,d,out)
    except Immediate as e:
        showversion=False
        if e.what=='help':out.append(Path(__file__).parent.joinpath('cfront/help.txt').read_text())
        elif e.what=='extra':out.append(Path(__file__).parent.joinpath('cfront/help-extra.txt').read_text())
        elif e.what=='version-number':out.append('0.9.28rc\n')
        elif e.what=='machine':out.append('x86_64-pc-linux-gnu\n')
        elif e.what=='version':out.append(VERSION)
        elif e.what=='paths':out.append(search_dirs(o))
        elif e.what=='verbose-paths':out.append(VERSION+search_dirs(o))
        elif e.what=='cross':
            path=os.path.dirname(sys.argv[0]) or '.'
            d.err.append("tcc: could not run '%s/i386-tcc'\n"%path)
        elif isinstance(e.what,tuple) and e.what[0]=='archive':
            from cfront.archive import archive
            code=archive(e.what[1],o,d,out);e.code=code
        code=e.code
    except StopCompilation:
        code=1
    if showversion and o.verbose:out.insert(0,VERSION)
    if o.ever_preprocess:
        text=''.join(pp.renderer.result() for pp in pps)
        if o.action!='preprocess' or not pps:text='\n'
        if output_file:
            output_file.write(text);output_file.close()
        else:out.append(text)
    sys.stdout.write(''.join(out));sys.stderr.write(''.join(d.err))
    return code

if __name__=='__main__':
    try:sys.exit(main())
    except BrokenPipeError:sys.exit(1)
