    def record_type(self):
        kind=self.take().text;attrs=self.attributes();tag=''
        if self.peek().kind=='id' and self.peek().text not in KEYWORDS:tag=self.take().text
        key=(kind,tag)
        t=self.tags.get(key) if tag else None
        if t is None:
            t=CType(kind,tag=tag)
            if tag:self.tags[key]=t
        if not self.consume('{'):return self.applyattrs(t,attrs)
        if kind=='enum':
            value=0
            while not self.at('}') and not self.at('<eof>'):
                name=self.identifier()
                if self.consume('='):
                    expr=self.expression(2)
                    if expr.value is None:self.diag.error('constant expression expected',self.peek())
                    value=int(expr.value)
