            self.attributes();ptrs.append(('ptr',con))
        name=None;ops=[]
        if self.at('(') and not (abstract and (self.peek(1).text in TYPEWORDS or self.peek(1).text==')')):
            self.take();name,ops=self.declarator_ops(abstract);self.expect(')')
        elif self.peek().kind=='id' and self.peek().text not in KEYWORDS|ATTRS:
            name=self.take()
        elif not abstract:self.diag.error('identifier expected',self.peek())
        while True:
            if self.consume('['):
                while self.peek().text in QUALS|{'static'}:self.take()
                if self.at(']'):count=None
                elif self.consume('*'):count=None
                else:
                    e=self.expression(2);count=e.value
                    if count is not None and count<0:self.diag.error('invalid array size',self.peek())
                self.expect(']');ops.append(('array',count))
            elif self.consume('('):
                params=[];variadic=False;oldstyle=False
                if self.consume(')'):oldstyle=True
                elif self.at('void') and self.peek(1).text==')':self.take();self.take()
