    def declarator(self,base,abstract=False):
        attrs=self.attributes()
        name,ops=self.declarator_ops(abstract)
        ty=replace(base)
        for op in reversed(ops):
            if op[0]=='ptr':ty=CType('ptr',ty,const=op[1])
            elif op[0]=='array':ty=CType('array',ty,count=op[1])
            elif op[0]=='func':ty=CType('func',ty,params=op[1],variadic=op[2],oldstyle=op[3])
        attrs.update(self.attributes());self.applyattrs(ty,attrs)
        return name,ty
    def typename_parse(self):
        t,_,_=self.specifiers(False);_,t=self.declarator(t,True);return t
    def compatible(self,a,b):
        if a.kind!=b.kind:return False
        if a.kind in ('ptr','array'):return self.compatible(a.base,b.base)
        if a.kind=='func':return self.compatible(a.base,b.base)
        if a.kind in ('struct','union'):return a.tag==b.tag
        return a.unsigned==b.unsigned

    def declaration(self,local=False):
        base,storage,seen=self.specifiers()
        if self.consume(';'):return Stmt('decl',[])
        declared=[]
        while True:
            token,ty=self.declarator(base)
            if token is None:self.diag.error('identifier expected',self.peek())
            name=token.text;alias=None
            if self.peek().text in ('asm','__asm','__asm__'):
                self.take();self.expect('(')
                if self.peek().kind=='str':alias=self.take().text[1:-1]
                while not self.at(')') and not self.at('<eof>'):self.take()
                self.expect(')')
            self.applyattrs(ty,self.attributes())
            previous=self.scopes[-1].get(name)
            if previous:
                if local and storage not in ('typedef','extern') and ty.kind!='func':self.diag.error("redeclaration of '%s'"%name,token)
                if not self.compatible(previous.type,ty):self.diag.error("incompatible types for redefinition of '%s'"%name,token)
                sym=previous
                if ty.kind=='func' and not ty.oldstyle:sym.type=ty
            else:
                sym=Symbol(name,ty,token,storage,local=local,alias=alias)
                self.scopes[-1][name]=sym
                if local and self.current:self.current.locals.append(sym)
            if ty.kind=='func' and ty.oldstyle and self.typename() and not self.at('{'):
                # Old-style argument declarations precede the function body.
                while self.typename() and not self.at('{'):
                    pt,_,_=self.specifiers()
                    while True:
                        pn,pt1=self.declarator(pt)
                        for param in ty.params or []:
                            if param.name==pn.text:param.type=pt1
                        if not self.consume(','):break
                    self.expect(';')
            if ty.kind=='func' and self.at('{'):
                if sym.defined:self.diag.error("redefinition of '%s'"%name,token)
                sym.defined=True;sym.storage=storage;sym.type=ty
                old=self.current;self.current=sym
                self.labels={};self.gotos=[]
                self.scopes.append({})
                for param in ty.params or []:
                    self.scopes[-1][param.name]=param
                    sym.locals.append(param)
                sym.body=self.compound(False)
                for label,tok in self.gotos:
                    if label not in self.labels:self.diag.error("label '%s' used but not defined"%label,self.peek())
                self.scopes.pop();self.current=old
