    def initializer(self,ty):
        if self.consume('{'):
            values=[];index=0
            fields=list(ty.fields) if ty.kind in ('struct','union') else []
            while not self.at('}') and not self.at('<eof>'):
                target=None
                while self.at('.') or self.at('['):
                    if self.consume('.'):
                        target=self.identifier().text
                        if target in fields:index=fields.index(target)
                    else:
                        self.take();target=self.expression(2).value
                        if self.consume('...'):self.expression(2)
                        self.expect(']')
                        if target is not None:index=int(target)
                if target is not None:self.consume('=')
                if ty.kind=='array':sub=ty.base
                elif fields and index<len(fields):sub=ty.fields[fields[index]][0]
                else:sub=ty
                val=self.initializer(sub);values.append((index,val));index+=1
                if not self.consume(','):break
            self.expect('}')
            if ty.kind=='array' and ty.count is None:ty.count=index
            return values
        e=self.expression(2)
        if ty.kind=='array' and e.op=='string':
            if ty.count is None:ty.count=e.type.count
        else:self.convert(ty,e,self.peek())
        return e

    def static_assert(self):
        self.take();self.expect('(');e=self.expression(2);message='_Static_assert fail'
        if self.consume(','):
            if self.peek().kind!='str':self.diag.error('string constant expected',self.peek())
            message=self.string_value(self.take().text)
        self.expect(')')
        if e.value is None:self.diag.error('constant expression expected',self.peek())
        if not e.value:self.diag.error(message,self.peek())
        self.expect(';')
    def parse(self):
        while not self.at('<eof>'):
            old=self.i
            if self.consume(';'):continue
            if self.at('_Static_assert'):self.static_assert()
            elif self.peek().text in ('asm','__asm','__asm__'):self.asm_statement()
            else:self.declaration(False)
            if self.i==old:self.take()
        return self.program

    @staticmethod
    def string_value(text):
        text=text[text.find('"'):]
        try:return ast.literal_eval(text)
        except (SyntaxError,ValueError):return text[1:-1]
    def ref(self,sym):
        if not self.unevaluated and not sym.local and sym.storage!='enum' and sym.name not in self.program.references:
            self.program.references.append(sym.name)
    def convert(self,ty,e,where):
        a=ty.decay();b=e.type.decay()
        if a.kind=='ptr' and b.integer() and e.value!=0:
            self.diag.warning('assignment makes pointer from integer without a cast',where)
        elif a.integer() and b.kind=='ptr':
            self.diag.warning('assignment makes integer from pointer without a cast',where)
            if a.size()!=b.size():self.diag.warning('cast between pointer and integer of different size',where)
        elif a.kind=='ptr' and b.kind=='ptr':
            if b.base.const and not a.base.const:self.diag.warning('assignment discards qualifiers from pointer target type',where,'discarded-qualifiers')
            if a.base.kind!='void' and b.base.kind!='void' and not self.compatible(replace(a.base,const=False),replace(b.base,const=False)):
                self.diag.warning('assignment from incompatible pointer type',where)
        elif a.kind in ('struct','union') and (b.kind!=a.kind or b.tag!=a.tag):self.diag.error('incompatible types for assignment',where)

    def expression(self,minimum=1):
        left=self.unary()
        while PRECEDENCE.get(self.peek().text,0)>=minimum:
            tok=self.take();op=tok.text;p=PRECEDENCE[op]
            if op=='?':
                mid=left if self.at(':') else self.expression(1)
                self.expect(':');right=self.expression(3)
                value=(mid.value if left.value else right.value) if left.value is not None else None
                left=Expr('?:',[left,mid,right],value,mid.type,tok)
                continue
            right=self.expression(p if p==2 else p+1)
            if p==2:
                if not left.lvalue:self.diag.error('lvalue expected',tok)
                if left.type.const:self.diag.warning('assignment of read-only location',self.peek())
                if op=='=':self.convert(left.type,right,self.peek())
                left=Expr(op,[left,right],None,left.type,tok)
                continue
            value=None;typ=left.type.decay()
            if op in ('==','!=','<','>','<=','>=','&&','||'):typ=INT
            elif op==',':typ=right.type
            elif typ.kind=='ptr' and right.type.decay().kind=='ptr' and op=='-':typ=LONG
            elif right.type.floating() or left.type.floating():
                typ=CType('ldouble' if 'ldouble' in (left.type.kind,right.type.kind) else 'double' if 'double' in (left.type.kind,right.type.kind) else 'float')
            elif right.type.size()>typ.size() and right.type.kind!='ptr':typ=right.type
            elif typ.integer() and typ.size()<4:typ=INT
            if left.value is not None and right.value is not None:
                try:value=apply(op,left.value,right.value)
                except ZeroDivisionError:
                    if self.constant_context:self.diag.error('division by zero in constant',tok)
                except (ValueError,TypeError,OverflowError):pass
            elif op=='&&' and left.value==0:value=0
            elif op=='||' and left.value is not None and left.value!=0:value=1
            left=Expr(op,[left,right],value,typ,tok)
        return left
    def unary(self):
        tok=self.peek();op=tok.text
        if op in ('+','-','!','~','*','&','++','--'):
            self.take();e=self.unary();typ=e.type;lv=False;val=None
            if op=='*':
                typ=typ.decay()
                if typ.kind!='ptr':self.diag.error('pointer expected',tok)
                typ=typ.base;lv=True
            elif op=='&':
                if not e.lvalue and e.type.kind not in ('func','array'):self.diag.error('lvalue expected',tok)
                typ=typ.pointer()
            elif op in ('++','--'):
                if not e.lvalue:self.diag.error('lvalue expected',tok)
                if e.type.const:self.diag.warning('assignment of read-only location',self.peek())
            elif e.value is not None:
                if op=='+':val=e.value
                if op=='-':val=-e.value
                if op=='!':val=int(not e.value);typ=INT
                if op=='~':val=~int(e.value)
            return Expr('u'+op,[e],val,typ,tok,lv)
        if op in ('sizeof','_Alignof','__alignof','__alignof__'):
            self.take();self.unevaluated+=1
            if self.at('(') and self.typename(self.peek(1)):
                self.take();ty=self.typename_parse();self.expect(')')
                if self.at('{'):self.initializer(ty)
            else:ty=self.unary().type
            self.unevaluated-=1
            val=ty.size() if op=='sizeof' else ty.align()
            return Expr('const',value=val,type=CType('long',unsigned=True),token=tok)
        if op=='__extension__':self.take();return self.unary()
        if op=='(' and self.typename(self.peek(1)):
