                except (ValueError,TypeError):val=None
            return Expr('cast',[e],val,ty,tok)
        return self.postfix(self.primary())

    def primary(self):
        tok=self.take();text=tok.text
        if tok.kind in ('num','char'):
            try:value=number(text)
            except ValueError:self.diag.error('invalid number',tok)
            kind='int';uns=False
            if tok.kind=='num':
                if isinstance(value,float):kind='float' if text.lower().endswith('f') else 'ldouble' if text.lower().endswith('l') else 'double'
                else:
                    uns='u' in text.lower()
                    if 'll' in text.lower():kind='llong'
                    elif text.lower().endswith(('l','lu','ul')) or value>0xffffffff:kind='long'
                    elif value>0x7fffffff:uns=True
            return Expr('const',value=value,type=CType(kind,unsigned=uns),token=tok)
        if tok.kind=='str':
            s=self.string_value(text)
            while self.peek().kind=='str':s+=self.string_value(self.take().text)
            typ=CType('array',replace(CHAR,const=self.options.warn_write_strings),count=len(s.encode('utf-8'))+1)
            expr=Expr('string',value=s,type=typ,token=tok,lvalue=True)
            self.program.strings.append(expr);return expr
        if text=='(':
            if self.at('{'):
                body=self.compound();self.expect(')');return Expr('stmt-expr',[body],type=INT,token=tok)
            e=self.expression();self.expect(')');return e
        if text in ('__func__','__FUNCTION__'):
            name=self.current.name if self.current else ''
            return Expr('string',value=name,type=CType('array',CHAR,count=len(name)+1),token=tok,lvalue=True)
        if text=='_Generic':
            self.expect('(');control=self.expression(2);self.expect(',');selected=None;fallback=None
            while not self.at(')'):
                if self.consume('default'):ty=None
                else:ty=self.typename_parse()
                self.expect(':');e=self.expression(2)
                if ty is None:fallback=e
                elif self.compatible(ty,control.type):selected=e
                if not self.consume(','):break
            self.expect(')')
            if selected is None:selected=fallback
            if selected is None:self.diag.error('type match failed',tok)
            return selected
        if text in ('__builtin_types_compatible_p','__builtin_constant_p','__builtin_choose_expr','__builtin_offsetof'):
            return self.builtin(text,tok)
        if tok.kind=='id':
            sym=self.find(text)
            if sym is None:
                if self.at('('):
                    if text not in ('__builtin_expect','__builtin_memcpy','__builtin_memset','__builtin_alloca','__builtin_frame_address','__builtin_return_address','__builtin_va_start','__builtin_va_end','__builtin_va_copy','__builtin_bswap16','__builtin_bswap32','__builtin_bswap64'):
                        self.diag.warning("implicit declaration of function '%s'"%text,tok,'implicit-function-declaration')
                    sym=Symbol(text,CType('func',INT,params=[],oldstyle=True),tok,'extern')
                    self.scopes[0][text]=sym
                else:self.diag.error("'%s' undeclared"%text,tok)
            if sym.storage=='typedef':self.diag.error("expression expected before '%s'"%text,tok)
            self.ref(sym)
            return Expr('var',value=sym.value if sym.storage=='enum' else None,type=sym.type,token=tok,lvalue=sym.type.kind!='func',symbol=sym)
        self.diag.error("expression expected before '%s'"%text,tok)

    def builtin(self,name,tok):
        self.expect('(')
        if name=='__builtin_types_compatible_p':
            a=self.typename_parse();self.expect(',');b=self.typename_parse();self.expect(')')
            return Expr('const',value=int(self.compatible(a,b)),type=INT,token=tok)
        if name=='__builtin_constant_p':
            self.unevaluated+=1;e=self.expression(2);self.unevaluated-=1;self.expect(')')
            return Expr('const',value=int(e.value is not None),type=INT,token=tok)
        if name=='__builtin_choose_expr':
            c=self.expression(2);self.expect(',');a=self.expression(2);self.expect(',');b=self.expression(2);self.expect(')')
            return a if c.value else b
        ty=self.typename_parse();self.expect(',');value=0
        while not self.at(')'):
            nm=self.identifier()
            if nm.text not in ty.fields:self.diag.error('field not found: '+nm.text,nm)
            ty,off=ty.fields[nm.text];value+=off
            while self.consume('['):
                e=self.expression();self.expect(']');ty=ty.base;value+=(e.value or 0)*ty.size()
            if not self.consume('.'):break
        self.expect(')');return Expr('const',value=value,type=LONG,token=tok)

    def postfix(self,e):
        while True:
            tok=self.peek()
            if self.consume('('):
                args=[]
                if not self.at(')'):
                    while True:
                        args.append(self.expression(2))
                        if not self.consume(','):break
                self.expect(')')
                ty=e.type
                if ty.kind=='ptr':ty=ty.base
                if ty.kind!='func':self.diag.error('function pointer expected',tok)
                if not ty.oldstyle:
                    if len(args)<len(ty.params):self.diag.error('too few arguments to function',self.peek())
                    if len(args)>len(ty.params) and not ty.variadic:self.diag.error('too many arguments to function',self.peek())
                    for p,a in zip(ty.params,args):self.convert(p.type,a,self.peek())
                value=None
                if e.symbol and e.symbol.name=='__builtin_expect' and args:value=args[0].value
                e=Expr('call',[e]+args,value,ty.base,tok)
            elif self.consume('['):
                index=self.expression();self.expect(']');ty=e.type.decay()
                if ty.kind!='ptr':
                    if index.type.decay().kind=='ptr':e,index=index,e;ty=e.type.decay()
                    else:self.diag.error('pointer expected',tok)
                e=Expr('index',[e,index],type=ty.base,token=tok,lvalue=True)
            elif self.peek().text in ('.','->'):
                operator=self.take().text;ty=e.type
                if operator=='->':
                    ty=ty.decay()
                    if ty.kind!='ptr':self.diag.error('pointer expected',tok)
                    ty=ty.base
                if ty.kind not in ('struct','union'):self.diag.error('struct or union expected',tok)
                nm=self.identifier()
                if nm.text not in ty.fields:self.diag.error('field not found: '+nm.text,nm)
                sub,off=ty.fields[nm.text];e=Expr(operator,[e,off],type=sub,token=tok,lvalue=True)
            elif self.peek().text in ('++','--'):
                operator=self.take().text
                if not e.lvalue:self.diag.error('lvalue expected',tok)
                e=Expr('post'+operator,[e],type=e.type,token=tok)
            else:break
        return e

    def compound(self,push=True):
        tok=self.expect('{')
        if push:self.scopes.append({})
        stmts=[]
