    symbols={}
    refs=[]
    for p in programs:
        for name,s in p.symbols.items():
            if s.storage in ('typedef','enum'):continue
            defined=s.type.kind!='func' and s.storage!='extern' or s.body is not None
            if defined:
                if name in definitions and s.storage!='static':diag.error("'%s' defined twice"%name)
                definitions[name]=s
            symbols[name]=s
        for r in p.references:
            if r not in refs:refs.append(r)
    run=o.action=='run'
    def missing(name):
        for p in [o.root]+o.libraries:
            if os.path.isfile(os.path.join(p,name)):return False
        diag.error("file '%s' not found"%name,fatal=False)
        return True
    if run:missing('runmain.o')
    if o.bounds:missing('bcheck.o')
    if o.backtrace or (run and o.debug):
        if not run:missing('bt-exe.o')
        missing('bt-log.o')
    if not o.nostdlib:missing('libtcc1.a')
    if o.verbose>=2 and not o.nostdlib:
        out.extend(['-> /usr/lib/x86_64-linux-gnu/libc.so\n','-> /lib/x86_64-linux-gnu/libc.so.6\n',
                    '-> /usr/lib/x86_64-linux-gnu/libc_nonshared.a\n','-> /lib64/ld-linux-x86-64.so.2\n'])
    if run and not o.nostdlib:return 1
    libs=[]
    if not o.nostdlib:libs.append(ctypes.CDLL(None))
    for kind,name,_ in o.inputs:
        if kind=='library':
            for suffix in ('.so.6','.so.2','.so.1','.so'):
                try:libs.append(ctypes.CDLL('lib'+name+suffix));break
                except OSError:pass
    if not run and o.action!='shared' and not o.nostdlib and 'main' not in definitions:refs.insert(0,'main')
    if not run and (o.backtrace or o.bounds):refs+=['__bt_init','__bt_exit']
    undefined=[]
    for name in refs:
        if name in definitions or name.startswith('__builtin_'):continue
        known=False
        for lib in libs:
            try:getattr(lib,name);known=True;break
            except AttributeError:pass
        if not known:undefined.append(name)
    if o.action!='shared':
        for name in undefined:diag.error("undefined symbol '%s'"%name,fatal=False)
        if undefined:return 1
    if run:
        if '_runmain' not in definitions:
            diag.error('_runmain not defined',fatal=False);return 1
        from .runtime import Interpreter
        vm=Interpreter(programs,o,out)
        try:return int(vm.call('_runmain',[len(o.run_args)+1,[programs[0].file]+o.run_args]))&255
        except Exception:return 1
    if o.action=='link' and o.nostdlib and '_start' not in definitions:
        diag.error('_start not defined',fatal=False);return 1
    if diag.errors:return 1
    from .elf import write_executable
    dest=o.output or 'a.out'
    write_executable(dest,programs,o,diag)
    if o.verbose:out.append('<- '+dest+'\n')
    return 0
