            self.sections.append(sec);self.byname[name]=sec
        self.symbols=[]
        tables=[s for s in self.sections if s.type==2] or [s for s in self.sections if s.type==11]
        if tables:
            tab=tables[0];strings=self.sections[tab.link].data
            for i in range(0,len(tab.data),tab.entsize or 24):
                n,info,other,section,value,size=struct.unpack_from('<IBBHQQ',tab.data,i)
                name=strings[n:].split(b'\0',1)[0].decode('utf-8','surrogateescape')
                self.symbols.append(ObjectSymbol(name,info,other,section,value,size))
    def relocations(self):
        for s in self.sections:
            if s.type==4:
                for i in range(0,len(s.data),s.entsize or 24):
                    offset,info,addend=struct.unpack_from('<QQq',s.data,i)
                    yield s.info,offset,info>>32,info&0xffffffff,addend


def load_program(name,data):
