        kind=s.info&15
        function=kind in (2,10)
        if kind==0 and 0<s.section<len(image.sections) and image.sections[s.section].flags&4:function=True
        typ=CType('func',INT,params=[],oldstyle=True) if function else CType('int',bytes=s.size or 4)
        sym=Symbol(s.name,typ,storage='' if s.section else 'extern',defined=bool(s.section))
